SELECT COUNT(*) AS n_rows, COUNTIF(value IS NOT NULL) AS n_nonnull, MIN(period) AS first_period, MAX(period) AS last_period, ANY_VALUE(value HAVING MAX period) AS last_value FROM (SELECT * FROM (SELECT FORMAT_DATE('%Y-%m', period) AS period, value FROM `project-for-method-dw.revenue_metrics.v_metric__sync_conversion_rate_forecasted` ORDER BY 1) sub WHERE period >= FORMAT_DATE('%Y-%m', DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 13 MONTH), MONTH)))